using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.USR.Modelos;namespace GraphApi.Services.USR.Modelos{    public class ModelosService : IModelosService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public ModelosService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadModelos>> GetModelos(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM usr.Modelos (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadModelos>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetModelosDynamic(            int? modeloID,            int? marcaID,            string? modelo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "ModeloID, MarcaID, Modelo, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM usr.Modelos (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (modeloID.HasValue)            {                vSql.Append(" AND ModeloID = @ModeloID");                vParameters.Add("ModeloID",modeloID);            }            if (!string.IsNullOrWhiteSpace(modelo))            {                vSql.Append(" AND Modelo LIKE @Modelo");                vParameters.Add("Modelo",$"%{modelo}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadModelos> CreateModelos(clCreateModelos objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO usr.Modelos                (MarcaID, Modelo, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@MarcaID, @Modelo, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.MarcaID,                objInput.Modelo,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT ModeloID, MarcaID, Modelo, bEliminado                FROM usr.Modelos (NOLOCK)                WHERE ModeloID = @ModeloID;";            var vReadParams = new { ModeloID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadModelos>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Modelo con ID {vNewId}.");            return vCreated;        }        public async Task<clReadModelos?> UpdateModelos(clUpdateModelos objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("ModeloID", objInput.ModeloID);            if (objInput.MarcaID != null)            {                vSets.Add("MarcaID = @MarcaID");                vParameters.Add("MarcaID", objInput.MarcaID);            }            if (objInput.Modelo is not null)            {                vSets.Add("Modelo = @Modelo");                vParameters.Add("Modelo", objInput.Modelo);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE usr.Modelos                SET {vSetClause}                WHERE ModeloID = @ModeloID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT ModeloID, MarcaID, Modelo, bEliminado                FROM usr.Modelos (NOLOCK)                WHERE ModeloID = @ModeloID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadModelos>(sSelect, new {  objInput.ModeloID });        }        public async Task<bool> DeleteModelos(int nModelosID)        {            const string sSql = @"                DELETE FROM usr.Modelos                WHERE ModeloID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nModelosID });            return vAffected > 0;        }    }}